/* --- 消息勾选框：确保仅在删除模式下可见且不被雪景遮挡 --- */

/* 1. 修正复选框容器的层级和定位 */
/* 当系统激活删除模式时，.for_checkbox 会被取消 display: none */
.mes .for_checkbox {
    position: absolute !important;
    top: 15px !important;    /* 距离顶部距离 */
    left: 15px !important;   /* 距离左侧距离 */
    z-index: 100 !important; /* 必须高于所有背景装饰和头像框 */
    width: 24px !important;
    height: 24px !important;
    pointer-events: auto !important;
}

/* 2. 强制复选框在“删除模式”下显示原生对勾 */
.mes input[type='checkbox'].del_checkbox {
    width: 22px !important;
    height: 22px !important;
    margin: 0 !important;
    cursor: pointer !important;

    /* 核心：重置外观，确保不被自定义样式污染 */
    appearance: checkbox !important;
    -webkit-appearance: checkbox !important;
    opacity: 1 !important;
    visibility: visible !important;

    /* 增加一个明显的白影，防止在复杂的背景图上看不清 */
    filter: drop-shadow(0 0 3px white) !important;
}

/* 3. 重要：将之前设置的头像背景装饰图降级，防止遮挡对勾 */
.mesAvatarWrapper::before {
    z-index: -1 !important; /* 确保背景图在所有内容的最后面 */
}

/* 4. 重要：将头像和名字区域层级稍微调低，确保复选框在最前面 */
.avatar, .ch_name {
    z-index: 1 !important;
}

/* 5. 提示：当消息被选中时，给气泡加个半透明边框反馈 */
.mes.selected {
    outline: 2px solid var(--classic-ink) !important;
    outline-offset: -2px !important;
